<?php
declare(strict_types=1);
// Alle Verträge: Entwürfe, versendet, aktiv mit Fristen, gekündigt. Firmendaten für den Vertragskopf, Automatik an/aus.
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');
require_once dirname(__DIR__).'/private/ui.php';require_once dirname(__DIR__).'/private/contracts.php';$admin=(int)$_SESSION['admin_id'];
if(!gszContractsReady($pdo)){gszPageStart('Verträge');echo '<div class="empty"><strong>Update nötig.</strong>Verträge gibt es ab Stand 450 – bitte unter Einstellungen → Update aktualisieren.</div>';gszPageEnd();exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$a=(string)($_POST['action']??'');
 if($a==='settings'){gszContractSettingsSave($pdo,$admin,$_POST);$_SESSION['app_notice']='Vertragsdaten gespeichert.';}
 elseif($a==='missing'){$n=gszContractCreateMissing($pdo,$admin);$_SESSION['app_notice']=$n?($n===1?'1 Vertragsentwurf angelegt.':$n.' Vertragsentwürfe angelegt.'):'Alle Objekte haben schon einen Vertrag.';}
 else throw new RuntimeException('Aktion unbekannt.');}catch(Throwable $e){$_SESSION['app_error']=$e instanceof InvalidArgumentException||$e instanceof RuntimeException?$e->getMessage():'Speichern fehlgeschlagen.';}redirect('vertraege.php'.(($_POST['action']??'')==='settings'?'#firma':''));}
$filter=(string)($_GET['f']??'');$rows=$pdo->query('SELECT c.*,p.name property_name FROM property_contracts c LEFT JOIN properties p ON p.id=c.property_id ORDER BY FIELD(c.status,\'entwurf\',\'versendet\',\'aktiv\',\'gekuendigt\',\'beendet\'),c.object_name,c.id LIMIT 1000')->fetchAll(PDO::FETCH_ASSOC);
$count=array_count_values(array_column($rows,'status'));$without=(int)$pdo->query('SELECT COUNT(*) FROM properties p WHERE NOT EXISTS(SELECT 1 FROM property_contracts c WHERE c.property_id=p.id)')->fetchColumn();
$monthly=0;foreach($rows as $r)if($r['status']==='aktiv'&&$r['price_cents']!==null)$monthly+=match($r['price_period']){'year'=>intdiv((int)$r['price_cents'],12),'visit'=>0,default=>(int)$r['price_cents']};
$shown=$filter&&isset(GSZ_CONTRACT_STATUS[$filter])?array_filter($rows,fn($r)=>$r['status']===$filter):$rows;$att=gszContractAttention($pdo);
$companyMissing=gszSetting($pdo,'company_address')==='';
gszPageStart('Verträge','Ein Vertrag je Objekt – entsteht automatisch beim Anlegen.');
foreach(['app_error'=>'error','app_notice'=>'notice'] as $k=>$cls)if(isset($_SESSION[$k])){echo '<p class="'.$cls.' flash" role="'.($cls==='error'?'alert':'status').'">'.e($_SESSION[$k]).'</p>';unset($_SESSION[$k]);}?>
<?php if($companyMissing):?><p class="error">Deine Firmenanschrift fehlt noch im Vertragskopf. <a href="#firma">Jetzt eintragen</a></p><?php endif?>
<nav class="day-kpis" aria-label="Verträge"><a class="dk<?=($count['entwurf']??0)?' is-warn':''?>" href="?f=entwurf"><strong><?=$count['entwurf']??0?></strong><span>Entwürfe</span></a><a class="dk" href="?f=versendet"><strong><?=$count['versendet']??0?></strong><span>versendet</span></a><a class="dk" href="?f=aktiv"><strong><?=$count['aktiv']??0?></strong><span>aktiv</span><?php if($monthly):?><small><?=e(moneyDisplay($monthly))?> / Monat</small><?php endif?></a><div class="dk<?=$without?' is-warn':''?>"><strong><?=$without?></strong><span>Objekte ohne Vertrag</span></div></nav>
<?php if($without):?><form method="post" class="estate-actions"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="missing"><button class="primary">Entwürfe für <?=$without===1?'1 Objekt':$without.' Objekte'?> ohne Vertrag anlegen</button></form><?php endif?>
<?php if($att):?><h2 class="section-title">Fristen &amp; Nachfassen</h2><div class="task-feed"><?php foreach($att as [$u,$t]):?><a class="tf tf-amber" href="<?=e($u)?>"><span class="tf-dot" aria-hidden="true"></span><span><strong><?=e($t)?></strong></span></a><?php endforeach?></div><?php endif?>
<nav class="seg-tabs" aria-label="Filter"><a href="vertraege.php"<?=!$filter?' aria-current="page"':''?>>Alle <span class="count"><?=count($rows)?></span></a><?php foreach(GSZ_CONTRACT_STATUS as $k=>[$l]):if(empty($count[$k]))continue;?><a href="?f=<?=$k?>"<?=$filter===$k?' aria-current="page"':''?>><?=e($l)?> <span class="count"><?=$count[$k]?></span></a><?php endforeach?></nav>
<?php if(!$shown):?><div class="empty"><strong>Noch keine Verträge.</strong>Beim nächsten neuen Objekt legt die Zentrale automatisch einen Entwurf an.</div><?php else:?><div class="list"><?php foreach($shown as $r):[$l,$cls]=GSZ_CONTRACT_STATUS[$r['status']];$per=$r['status']==='aktiv'?gszContractPeriod($r):null;$miss=$r['status']==='entwurf'?gszContractProblems($r):[];?>
<a href="vertrag.php?id=<?=(int)$r['id']?>"><span class="name"><?=e($r['object_name'])?><span class="sub"><?=e(gszContractNo($r))?><?=$r['client_name']!==''?' · '.e($r['client_name']):''?><?=$r['price_cents']!==null?' · '.e(moneyDisplay((int)$r['price_cents'])):''?><?=$per&&$per['notice_by']?' · Kündigung bis '.e((new DateTimeImmutable($per['notice_by']))->format('d.m.Y')):''?><?=$miss?' · fehlt: '.e(implode(', ',$miss)):''?></span></span><span class="pill <?=e($cls)?>"><?=e($l)?></span></a><?php endforeach?></div><?php endif?>
<details class="card" id="firma"<?=$companyMissing?' open':''?>><summary>Firmendaten &amp; Standardwerte für Verträge</summary><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="settings">
<div class="form-grid"><label>Firmenname<input name="company" maxlength="190" value="<?=e(gszSetting($pdo,'company'))?>"></label><label>Inhaber<input name="owner_name" maxlength="120" value="<?=e(gszSetting($pdo,'owner_name'))?>"></label>
<label>Anschrift<textarea name="company_address" maxlength="500" rows="2" placeholder="Straße Nr.&#10;PLZ Ort"><?=e(gszSetting($pdo,'company_address'))?></textarea></label><label>Telefon<input name="company_phone" maxlength="40" value="<?=e(gszSetting($pdo,'company_phone'))?>"></label>
<label>E-Mail<input type="email" name="company_email" maxlength="190" value="<?=e(gszSetting($pdo,'company_email'))?>"></label><label>Steuernummer oder USt-IdNr. (optional)<input name="company_taxid" maxlength="60" value="<?=e(gszSetting($pdo,'company_taxid'))?>"></label></div>
<div class="form-grid three"><label>Erstlaufzeit (Monate)<input type="number" name="contract_term" min="1" max="60" value="<?=e(gszSetting($pdo,'contract_term'))?>"></label><label>Kündigungsfrist (Monate)<input type="number" name="contract_notice" min="1" max="12" value="<?=e(gszSetting($pdo,'contract_notice'))?>"></label><label>Umsatzsteuer<select name="contract_vat"><?php foreach(['zzgl'=>'zzgl. USt','inkl'=>'inkl. USt','none'=>'keine USt (§ 19)'] as $k=>$v):?><option value="<?=$k?>"<?=gszSetting($pdo,'contract_vat')===$k?' selected':''?>><?=e($v)?></option><?php endforeach?></select></label></div>
<label class="check-label"><input type="checkbox" name="contract_auto" value="1"<?=gszSetting($pdo,'contract_auto')==='1'?' checked':''?>> Beim Anlegen eines Objekts automatisch einen Vertragsentwurf erstellen</label>
<button class="primary">Speichern</button></form><p class="hint">Bei Verbrauchern (Privatkunden) gelten automatisch höchstens 24 Monate Erstlaufzeit und 1 Monat Kündigungsfrist.</p></details>
